#!/usr/bin/env python3
"""Generate deterministic compile-time sine LUT; development tool, not in firmware."""
import math
from pathlib import Path
N=1024
p=Path(__file__).resolve().parent/'gptfx_trig_lut.h'
values=[math.sin(2*math.pi*i/N) for i in range(N)]
with p.open('w') as f:
    f.write('''/*
 * GPT Matrix FX experimental sine LUT, generated by generate_lut.py.
 * 1024 float samples: 4096 bytes of static read-only flash data.
 * Cosine reuses the same table with a quarter-cycle offset.
 * The input angle is in radians, and the caller bounds large temporal
 * phases at frame granularity. The float-to-index conversion is only
 * defined for finite phase values whose magnitude is below 100000 rad.
 */
#pragma once
#include <cmath>
#include <cstdint>

namespace gptfx_trig {
constexpr int TABLE_BITS = 10;
constexpr int TABLE_SIZE = 1 << TABLE_BITS;
constexpr int TABLE_MASK = TABLE_SIZE - 1;
constexpr float INDEX_SCALE = 162.97466172610083f; // 1024 / (2*pi)
static const float sinTable[TABLE_SIZE] PROGMEM = {
''')
    for i in range(0,N,8):
        f.write('  '+', '.join(f'{v:.10g}f' if v not in (0.0,1.0,-1.0) else f'{v:.1f}f' for v in values[i:i+8])+(',\n' if i+8 <N else '\n'))
    f.write('''};

// Inputs used in GPT24b are within about +/- 80 radians. For exceptional
// values, preserve defined behavior by returning the standard implementation.
static inline bool withinRange(float x) {
  return x > -100000.0f && x < 100000.0f;
}
static inline float nearest(float x, int quarterTurn = 0) {
  if (!withinRange(x)) return quarterTurn ? cosf(x) : sinf(x);
  const int32_t i = (int32_t)floorf(x * INDEX_SCALE + 0.5f);
  return sinTable[(uint32_t)(i + quarterTurn) & TABLE_MASK];
}
static inline float linear(float x, int quarterTurn = 0) {
  if (!withinRange(x)) return quarterTurn ? cosf(x) : sinf(x);
  const float scaled = x * INDEX_SCALE;
  const float lower = floorf(scaled);
  const int32_t i = (int32_t)lower + quarterTurn;
  const float fraction = scaled - lower;
  const float a = sinTable[(uint32_t)i & TABLE_MASK];
  const float b = sinTable[(uint32_t)(i+1) & TABLE_MASK];
  return a + (b-a)*fraction;
}
static inline float sineNearest(float x) { return nearest(x); }
static inline float cosineNearest(float x) { return nearest(x, TABLE_SIZE/4); }
static inline float sineLinear(float x) { return linear(x); }
static inline float cosineLinear(float x) { return linear(x, TABLE_SIZE/4); }

#ifndef GPTFX_GPT24_TRIG_BACKEND
#define GPTFX_GPT24_TRIG_BACKEND 2
#endif
#if GPTFX_GPT24_TRIG_BACKEND < 0 || GPTFX_GPT24_TRIG_BACKEND > 2
#error "GPTFX_GPT24_TRIG_BACKEND must be 0 (libm), 1 (nearest) or 2 (linear LUT)"
#endif
static inline float sine(float x) {
#if GPTFX_GPT24_TRIG_BACKEND == 0
  return sinf(x);
#elif GPTFX_GPT24_TRIG_BACKEND == 1
  return sineNearest(x);
#else
  return sineLinear(x);
#endif
}
static inline float cosine(float x) {
#if GPTFX_GPT24_TRIG_BACKEND == 0
  return cosf(x);
#elif GPTFX_GPT24_TRIG_BACKEND == 1
  return cosineNearest(x);
#else
  return cosineLinear(x);
#endif
}
static inline const char* backendName() {
#if GPTFX_GPT24_TRIG_BACKEND == 0
  return "libm";
#elif GPTFX_GPT24_TRIG_BACKEND == 1
  return "lut1024-nearest";
#else
  return "lut1024-linear";
#endif
}
} // namespace gptfx_trig
''')
print(f'{p}: {p.stat().st_size} bytes')
